query fetchInstanceProjectsForArchive($Instance: String!) {
  instanceById(ID: $Instance) {
    identifier
    label
    description
    projects {
      identifier
      label
      description
      otherIdentifiers
      vendor {
        label
      }
      milestones {
        identifier
        label
        description
        acceptanceCriteria
        status
        value {
          assetId
          quantity
        }
        maturation {
          format
          unixMilli
        }
      }
    }
  }
}

